import type {TrackerSelectGroup} from '../../../components/TrackerSelect/types';

/**
 * Returns a tag-prefixed group name when the group has a tag, otherwise returns the group name as-is.
 */
export function getGroupName(group: TrackerSelectGroup): string | undefined {
    const tag = group.tag;

    return tag ? `${tag}: ${group.name}` : group.name;
}
